/** Emits the generated TypeScript models, validators, decoders and encoders. */

import {
  camelCase,
  pascalCase,
  resolveRef,
  type ArrayNode,
  type MessageSpec,
  type Node,
  type ObjectNode,
  type ProtocolModel,
  type PropertySpec,
} from "./schema-model.ts";

const BANNER = [
  "// Code generated by packages/protocol/tools/generate.ts from",
  "// schemas/connector/v1.schema.json. DO NOT EDIT.",
  "",
].join("\n");

function doc(text: string, indent = ""): string {
  if (text === "") return "";
  const width = 88 - indent.length;
  const words = text.split(/\s+/u);
  const lines: string[] = [];
  let line = "";
  for (const word of words) {
    if (line === "") {
      line = word;
    } else if (`${line} ${word}`.length <= width) {
      line = `${line} ${word}`;
    } else {
      lines.push(line);
      line = word;
    }
  }
  if (line !== "") lines.push(line);
  return `${indent}/**\n${lines.map((entry) => `${indent} * ${entry}`).join("\n")}\n${indent} */`;
}

/** Pushes a doc comment, skipping empty ones so no blank line is emitted. */
function pushDoc(out: string[], text: string, indent = ""): void {
  const rendered = doc(text, indent);
  if (rendered !== "") out.push(rendered);
}

function literal(value: string): string {
  return JSON.stringify(value);
}

function unionType(values: readonly string[]): string {
  return values.map((value) => literal(value)).join("\n  | ");
}

function tsScalarTypeName(defName: string, node: Node): string {
  if (node.kind === "string" && node.sensitive) return "SensitiveString";
  if (node.kind === "string" && node.enumTypeName !== null) return node.enumTypeName;
  return pascalCase(defName);
}

function tsTypeOf(model: ProtocolModel, property: PropertySpec): string {
  if (property.ref !== null) {
    const target = resolveRef(model, property.ref);
    if (target.kind === "object") return target.typeName;
    return tsScalarTypeName(property.ref, target);
  }
  return tsTypeOfNode(model, property.node);
}

function tsTypeOfNode(model: ProtocolModel, node: Node): string {
  switch (node.kind) {
    case "string":
      if (node.sensitive) return "SensitiveString";
      return node.enumTypeName ?? "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "array": {
      if (node.itemRef !== null) {
        const target = resolveRef(model, node.itemRef);
        const name =
          target.kind === "object" ? target.typeName : tsScalarTypeName(node.itemRef, target);
        return `readonly ${name}[]`;
      }
      return `readonly ${tsTypeOfNode(model, node.item)}[]`;
    }
    case "object":
      return node.typeName;
    case "dynamic":
      return "unknown";
  }
}

function objectDefs(model: ProtocolModel): { defName: string; node: ObjectNode }[] {
  const result: { defName: string; node: ObjectNode }[] = [];
  for (const defName of model.defOrder) {
    const node = model.defs.get(defName);
    if (node !== undefined && node.kind === "object") result.push({ defName, node });
  }
  return result;
}

function scalarDefs(model: ProtocolModel): { defName: string; node: Node }[] {
  const result: { defName: string; node: Node }[] = [];
  for (const defName of model.defOrder) {
    const node = model.defs.get(defName);
    if (node !== undefined && node.kind !== "object") result.push({ defName, node });
  }
  return result;
}

/** Name of the validator for a property that is not a `$ref`. */
function inlineValidatorName(owner: ObjectNode, property: PropertySpec): string {
  return `validate${owner.typeName}${pascalCase(property.name)}`;
}

function refValidatorName(refName: string): string {
  return `validate${pascalCase(refName)}`;
}

export function emitTypes(model: ProtocolModel): string {
  const out: string[] = [BANNER];
  out.push(`import type { SensitiveString } from "../../../sensitive.ts";\n`);

  pushDoc(out, `Protocol name, as it appears in ${model.title}.`);
  out.push(`export const PROTOCOL_NAME = ${literal(model.name)} as const;\n`);
  pushDoc(out, "Protocol version this build accepts. Stage 0 pins a single version; an envelope carrying any other value is rejected with PROTOCOL_UNSUPPORTED and is never best-effort parsed.");
  out.push(`export const PROTOCOL_VERSION = ${model.version} as const;\n`);

  pushDoc(out, "Byte bounds enforced on raw frames before deserialisation.");
  out.push("export const LIMITS = {");
  out.push(`  MAX_CONTROL_FRAME_BYTES: ${model.limits.max_control_frame_bytes},`);
  out.push(`  MAX_DATA_STREAM_HEADER_BYTES: ${model.limits.max_data_stream_header_bytes},`);
  out.push("} as const;\n");

  pushDoc(out, "Logical channels of the connector protocol.");
  out.push(`export const CHANNELS = [\n${[...model.channels.keys()].map((channel) => `  ${literal(channel)},`).join("\n")}\n] as const;\n`);
  out.push(`export type Channel = (typeof CHANNELS)[number];\n`);

  pushDoc(out, "Human-readable purpose of each channel.");
  out.push("export const CHANNEL_DESCRIPTIONS: Readonly<Record<Channel, string>> = {");
  for (const [channel, description] of model.channels) {
    out.push(`  ${literal(channel)}: ${literal(description)},`);
  }
  out.push("};\n");

  for (const enumType of model.enums) {
    pushDoc(out, enumType.description);
    out.push(
      `export const ${constantName(enumType.typeName)}_VALUES = [\n${enumType.values.map((value) => `  ${literal(value)},`).join("\n")}\n] as const;\n`,
    );
    out.push(`export type ${enumType.typeName} =\n  | ${unionType(enumType.values)};\n`);
  }

  pushDoc(out, "Which side of the trust boundary sends each message type.");
  out.push("export const MESSAGE_DIRECTIONS: Readonly<Record<MessageType, \"connector_to_control_plane\" | \"control_plane_to_connector\">> = {");
  for (const message of model.messages) {
    out.push(`  ${literal(message.type)}: ${literal(message.direction)},`);
  }
  out.push("};\n");

  pushDoc(out, "Channel each message type travels on.");
  out.push("export const MESSAGE_CHANNELS: Readonly<Record<MessageType, Channel>> = {");
  for (const message of model.messages) {
    out.push(`  ${literal(message.type)}: ${literal(message.channel)},`);
  }
  out.push("};\n");

  pushDoc(out, "Maximum canonical payload size for each message type. A payload larger than its bound is rejected.");
  out.push("export const PAYLOAD_MAX_BYTES: Readonly<Record<MessageType, number>> = {");
  for (const message of model.messages) {
    const payload = model.defs.get(message.payloadDef);
    if (payload === undefined || payload.kind !== "object" || payload.maxBytes === null) {
      throw new Error(`payload ${message.payloadDef} has no bound`);
    }
    out.push(`  ${literal(message.type)}: ${payload.maxBytes},`);
  }
  out.push("};\n");

  pushDoc(out, "Reasons a frame is refused. These classify local protocol failures; only some map to a wire error class.");
  out.push(
    `export const PROTOCOL_VIOLATION_REASONS = [\n${model.violationReasons.map((reason) => `  ${literal(reason.name)},`).join("\n")}\n] as const;\n`,
  );
  out.push(`export type ProtocolViolationReason = (typeof PROTOCOL_VIOLATION_REASONS)[number];\n`);

  pushDoc(out, "Connector error class reported for each rejection reason, where the protocol defines one.");
  out.push(
    "export const PROTOCOL_VIOLATION_ERROR_CLASS: Readonly<Record<ProtocolViolationReason, ErrorClass | null>> = {",
  );
  for (const reason of model.violationReasons) {
    out.push(`  ${literal(reason.name)}: ${reason.errorClass === null ? "null" : literal(reason.errorClass)},`);
  }
  out.push("};\n");

  pushDoc(out, "Codes attached to individual schema violations.");
  out.push(
    `export const SCHEMA_VIOLATION_CODES = [\n${model.schemaViolationCodes.map((code) => `  ${literal(code)},`).join("\n")}\n] as const;\n`,
  );
  out.push(`export type SchemaViolationCode = (typeof SCHEMA_VIOLATION_CODES)[number];\n`);

  pushDoc(out, "One schema failure, located by JSON path.");
  out.push("export interface SchemaViolation {");
  out.push("  readonly path: string;");
  out.push("  readonly code: SchemaViolationCode;");
  out.push("  readonly message: string;");
  out.push("}\n");

  pushDoc(out, "Capabilities known at this protocol version. Unknown capabilities are accepted so that a newer connector is classified rather than rejected.");
  out.push(
    `export const KNOWN_CAPABILITIES = [\n${model.knownCapabilities.map((value) => `  ${literal(value)},`).join("\n")}\n] as const;\n`,
  );
  out.push(
    `export const KNOWN_PLATFORMS = [\n${model.knownPlatforms.map((value) => `  ${literal(value)},`).join("\n")}\n] as const;\n`,
  );
  out.push(
    `export const KNOWN_ARCHITECTURES = [\n${model.knownArchitectures.map((value) => `  ${literal(value)},`).join("\n")}\n] as const;\n`,
  );

  pushDoc(out, "Conventional prefixes of the opaque identifiers carried by this protocol. They are documentation only: consumers MUST treat identifiers as opaque and validators MUST NOT require a prefix.");
  out.push("export const IDENTIFIER_PREFIXES: Readonly<Record<string, string>> = {");
  for (const [field, prefix] of model.identifierPrefixes) {
    out.push(`  ${literal(field)}: ${literal(prefix)},`);
  }
  out.push("};\n");

  for (const { defName, node } of scalarDefs(model)) {
    if (node.kind === "string" && node.enumTypeName !== null) continue;
    pushDoc(out, node.description);
    out.push(`export type ${pascalCase(defName)} = ${tsTypeOfNode(model, node)};\n`);
  }

  for (const { node } of objectDefs(model)) {
    pushDoc(out, node.description);
    out.push(`export interface ${node.typeName} {`);
    for (const property of node.properties) {
      if (property.node.kind === "dynamic" && property.ref === null) continue;
      pushDoc(out, property.description, "  ");
      out.push(
        `  readonly ${property.name}${property.optional ? "?" : ""}: ${tsTypeOf(model, property)};`,
      );
    }
    out.push("}\n");
  }

  pushDoc(out, "A decoded control frame: envelope header plus the payload selected by its type.");
  out.push("export type ConnectorFrame =");
  for (const message of model.messages) {
    const payload = model.defs.get(message.payloadDef);
    if (payload === undefined || payload.kind !== "object") throw new Error("bad payload");
    out.push(
      `  | {\n      readonly envelope: Envelope;\n      readonly type: ${literal(message.type)};\n      readonly payload: ${payload.typeName};\n    }`,
    );
  }
  out.push(";\n");

  return `${out.join("\n")}`;
}

function constantName(typeName: string): string {
  return typeName
    .replace(/([a-z0-9])([A-Z])/gu, "$1_$2")
    .replace(/([A-Z]+)([A-Z][a-z])/gu, "$1_$2")
    .toUpperCase();
}

function stringCheckOptions(node: {
  minLength: number | null;
  maxLength: number;
  enumValues: readonly string[] | null;
  patternConst: string | null;
}): string {
  const parts: string[] = [];
  if (node.enumValues !== null) {
    parts.push(`values: ${JSON.stringify(node.enumValues)}`);
  } else {
    if (node.minLength !== null) parts.push(`minLength: ${node.minLength}`);
    parts.push(`maxLength: ${node.maxLength}`);
    if (node.patternConst !== null) parts.push(`pattern: ${node.patternConst}`);
  }
  return `{ ${parts.join(", ")} }`;
}

export function emitValidate(model: ProtocolModel): string {
  const out: string[] = [BANNER];
  const patterns: string[] = [];
  const patternNames = new Map<string, string>();
  const used = new Set<string>();
  const use = (helper: string): string => {
    used.add(helper);
    return helper;
  };

  const patternConst = (pattern: string | null): string | null => {
    if (pattern === null) return null;
    const existing = patternNames.get(pattern);
    if (existing !== undefined) return existing;
    const name = `PATTERN_${patternNames.size}`;
    patternNames.set(pattern, name);
    patterns.push(`const ${name} = new RegExp(${literal(pattern)}, "u");`);
    return name;
  };

  const body: string[] = [];

  const emitScalarValidator = (name: string, node: Node, description: string): void => {
    pushDoc(body, description);
    body.push(
      `export function ${name}(value: unknown, path: string, out: SchemaViolation[]): void {`,
    );
    switch (node.kind) {
      case "string":
        body.push(
          `  ${use("checkString")}(value, path, out, ${stringCheckOptions({
            minLength: node.minLength,
            maxLength: node.maxLength,
            enumValues: node.enumValues,
            patternConst: patternConst(node.pattern),
          })});`,
        );
        break;
      case "integer":
        body.push(
          `  ${use("checkInteger")}(value, path, out, { minimum: ${node.minimum}, maximum: ${node.maximum} });`,
        );
        break;
      case "number":
        body.push(
          `  ${use("checkNumber")}(value, path, out, { minimum: ${node.minimum}, maximum: ${node.maximum} });`,
        );
        break;
      case "boolean":
        body.push(`  ${use("checkBoolean")}(value, path, out);`);
        break;
      case "array": {
        body.push(
          `  if (!${use("checkArray")}(value, path, out, { minItems: ${node.minItems}, maxItems: ${node.maxItems}, uniqueItems: ${node.uniqueItems} })) return;`,
        );
        const itemValidator =
          node.itemRef !== null ? refValidatorName(node.itemRef) : `${name}Item`;
        body.push("  for (let index = 0; index < value.length; index += 1) {");
        body.push(`    ${itemValidator}(value[index], \`\${path}[\${index}]\`, out);`);
        body.push("  }");
        break;
      }
      case "dynamic":
        body.push(`  ${use("checkPlainObject")}(value, path, out);`);
        break;
      case "object":
        throw new Error("objects use emitObjectValidator");
    }
    body.push("}\n");
  };

  for (const { defName, node } of scalarDefs(model)) {
    emitScalarValidator(refValidatorName(defName), node, node.description);
  }

  for (const { defName, node } of objectDefs(model)) {
    for (const property of node.properties) {
      if (property.ref !== null) continue;
      if (property.node.kind === "array" && property.node.itemRef === null) {
        emitScalarValidator(
          `${inlineValidatorName(node, property)}Item`,
          property.node.item,
          "",
        );
      }
      emitScalarValidator(
        inlineValidatorName(node, property),
        property.node,
        property.description,
      );
    }

    const propertyNames = node.properties.map((property) => literal(property.name));
    pushDoc(body, node.description);
    body.push(
      `export function ${refValidatorName(defName)}(value: unknown, path: string, out: SchemaViolation[]): void {`,
    );
    body.push(
      `  const source = ${use("checkObject")}(value, path, out, [${propertyNames.join(", ")}], [${node.required.map((name) => literal(name)).join(", ")}]);`,
    );
    body.push("  if (source === null) return;");
    for (const property of node.properties) {
      const validator =
        property.ref !== null
          ? refValidatorName(property.ref)
          : inlineValidatorName(node, property);
      body.push(`  if (source[${literal(property.name)}] !== undefined) {`);
      body.push(
        `    ${validator}(source[${literal(property.name)}], \`\${path}.${property.name}\`, out);`,
      );
      body.push("  }");
    }
    for (const rule of node.requires) {
      body.push(
        `  if (${use("matchesCondition")}(source[${literal(rule.whenProperty)}], [${rule.whenValues.map((value) => literal(value)).join(", ")}])) {`,
      );
      for (const required of rule.required) {
        body.push(
          `    ${use("requireProperty")}(source, path, ${literal(required)}, ${literal(rule.detail)}, out);`,
        );
      }
      for (const forbidden of rule.forbidden) {
        body.push(
          `    ${use("forbidProperty")}(source, path, ${literal(forbidden)}, ${literal(rule.detail)}, out);`,
        );
      }
      body.push("  }");
    }
    body.push("}\n");
  }

  const helperImports = [...used].sort().map((helper) => `  ${helper},`);
  out.push(
    [
      `import type { SchemaViolation } from "./types.ts";`,
      `import {`,
      ...helperImports,
      `} from "../../../validate-runtime.ts";`,
      "",
    ].join("\n"),
  );
  out.push(`${patterns.join("\n")}\n`);
  out.push(body.join("\n"));
  return out.join("\n");
}

function decodeExpression(model: ProtocolModel, property: PropertySpec, access: string): string {
  if (property.ref !== null) {
    const target = resolveRef(model, property.ref);
    return decodeNodeExpression(model, target, property.ref, access);
  }
  return decodeNodeExpression(model, property.node, null, access);
}

function decodeNodeExpression(
  model: ProtocolModel,
  node: Node,
  refName: string | null,
  access: string,
): string {
  switch (node.kind) {
    case "string":
      if (node.sensitive) return `new SensitiveString(${access} as string)`;
      if (node.enumTypeName !== null) return `${access} as ${node.enumTypeName}`;
      return `${access} as string`;
    case "integer":
    case "number":
      return `${access} as number`;
    case "boolean":
      return `${access} as boolean`;
    case "array": {
      const itemNode =
        node.itemRef !== null ? resolveRef(model, node.itemRef) : node.item;
      const inner = decodeNodeExpression(model, itemNode, node.itemRef, "item");
      return `(${access} as unknown[]).map((item) => ${inner})`;
    }
    case "object":
      return `decode${node.typeName}(${access})`;
    case "dynamic":
      return access;
  }
  throw new Error(`cannot decode ${refName ?? "node"}`);
}

export function emitDecode(model: ProtocolModel): string {
  const out: string[] = [BANNER];
  const typeImports: string[] = [];
  for (const { node } of objectDefs(model)) typeImports.push(node.typeName);
  for (const enumType of model.enums) typeImports.push(enumType.typeName);
  out.push(
    [
      doc(
        "Decoders build typed values from an already validated JSON tree. Calling a decoder on a value that has not passed its validator is a programming error; the frame entry points in frame.ts always validate first.",
      ).trimEnd(),
      "",
      `import { SensitiveString } from "../../../sensitive.ts";`,
      `import type {`,
      ...[...new Set(typeImports)].sort().map((name) => `  ${name},`),
      `} from "./types.ts";`,
      "",
    ].join("\n"),
  );

  for (const { node } of objectDefs(model)) {
    pushDoc(out, `Decodes a validated ${node.typeName}.`);
    out.push(`export function decode${node.typeName}(value: unknown): ${node.typeName} {`);
    out.push("  const source = value as Record<string, unknown>;");
    out.push("  return {");
    for (const property of node.properties) {
      if (property.node.kind === "dynamic" && property.ref === null) continue;
      const access = `source[${literal(property.name)}]`;
      const expression = decodeExpression(model, property, access);
      if (property.optional) {
        out.push(
          `    ...(${access} === undefined ? {} : { ${property.name}: ${expression} }),`,
        );
      } else {
        out.push(`    ${property.name}: ${expression},`);
      }
    }
    out.push("  };");
    out.push("}\n");
  }

  return out.join("\n");
}

function encodeExpression(model: ProtocolModel, property: PropertySpec, access: string): string {
  const node = property.ref !== null ? resolveRef(model, property.ref) : property.node;
  return encodeNodeExpression(model, node, access);
}

const encodeHelpers = new Set<string>();

function useEncodeHelper(helper: string): string {
  encodeHelpers.add(helper);
  return helper;
}

function encodeNodeExpression(model: ProtocolModel, node: Node, access: string): string {
  switch (node.kind) {
    case "string":
      if (node.sensitive) return `${useEncodeHelper("jsonString")}(${access}.reveal())`;
      return `${useEncodeHelper("jsonString")}(${access})`;
    case "integer":
      return `${useEncodeHelper("jsonInteger")}(${access})`;
    case "number":
      return `${useEncodeHelper("jsonNumber")}(${access})`;
    case "boolean":
      return `${useEncodeHelper("jsonBoolean")}(${access})`;
    case "array": {
      const itemNode = node.itemRef !== null ? resolveRef(model, node.itemRef) : node.item;
      const inner = encodeNodeExpression(model, itemNode, "item");
      return `\`[\${${access}.map((item) => ${inner}).join(",")}]\``;
    }
    case "object":
      return `encode${node.typeName}(${access})`;
    case "dynamic":
      return access;
  }
}

export function emitEncode(model: ProtocolModel): string {
  const typeImports = objectDefs(model).map(({ node }) => node.typeName);
  encodeHelpers.clear();
  const body: string[] = [];

  for (const { node } of objectDefs(model)) {
    const dynamic = node.properties.find(
      (property) => property.node.kind === "dynamic" && property.ref === null,
    );
    const signature =
      dynamic === undefined
        ? `export function encode${node.typeName}(value: ${node.typeName}): string {`
        : `export function encode${node.typeName}(value: ${node.typeName}, ${camelCase(dynamic.name)}Json: string): string {`;
    pushDoc(body, `Canonically encodes a ${node.typeName}.`);
    body.push(signature);
    body.push("  const fields: string[] = [];");
    for (const property of node.properties) {
      if (property.node.kind === "dynamic" && property.ref === null) {
        body.push(`  fields.push(\`${JSON.stringify(property.name)}:\${${camelCase(property.name)}Json}\`);`);
        continue;
      }
      const access = `value.${property.name}`;
      const expression = encodeExpression(model, property, access);
      if (property.optional) {
        body.push(`  if (${access} !== undefined) {`);
        body.push(`    fields.push(\`${JSON.stringify(property.name)}:\${${expression}}\`);`);
        body.push("  }");
      } else {
        body.push(`  fields.push(\`${JSON.stringify(property.name)}:\${${expression}}\`);`);
      }
    }
    body.push('  return `{${fields.join(",")}}`;');
    body.push("}\n");
  }

  const out: string[] = [BANNER];
  out.push(
    [
      doc(
        "Canonical encoders. Output is deterministic: properties appear in schema order, absent optional properties are omitted, and numbers and strings are formatted identically to the Go encoder so that both languages produce byte-identical frames.",
      ).trimEnd(),
      "",
      `import {`,
      ...[...encodeHelpers].sort().map((helper) => `  ${helper},`),
      `} from "../../../canonical.ts";`,
      `import type {`,
      ...[...new Set(typeImports)].sort().map((name) => `  ${name},`),
      `} from "./types.ts";`,
      "",
    ].join("\n"),
  );
  out.push(body.join("\n"));
  return out.join("\n");
}

export function emitDispatch(model: ProtocolModel): string {
  const out: string[] = [BANNER];
  const payloadTypeNames = model.messages.map((message) => payloadTypeName(model, message));
  out.push(
    [
      doc(
        "Type-directed dispatch generated from x-protocol.messages. Adding a message type to the schema is the only way to add one here.",
      ).trimEnd(),
      "",
      `import type { SchemaViolation } from "./types.ts";`,
      `import type {`,
      ...[...new Set(["ConnectorFrame", "Envelope", "MessageType", ...payloadTypeNames])]
        .sort()
        .map((name) => `  ${name},`),
      `} from "./types.ts";`,
      `import {`,
      ...[...new Set(payloadTypeNames)].sort().map((name) => `  decode${name},`),
      `} from "./decode.ts";`,
      `import {`,
      ...[...new Set(payloadTypeNames)].sort().map((name) => `  encode${name},`),
      `} from "./encode.ts";`,
      `import {`,
      ...[...new Set(payloadTypeNames)].sort().map((name) => `  validate${name},`),
      `} from "./validate.ts";`,
      "",
    ].join("\n"),
  );

  pushDoc(out, "Union of every version 1 payload.");
  out.push(`export type ConnectorPayload =\n  | ${[...new Set(payloadTypeNames)].join("\n  | ")};\n`);

  pushDoc(out, "Validates a payload against the schema selected by message type.");
  out.push(
    "export function validatePayload(type: MessageType, value: unknown, path: string, out: SchemaViolation[]): void {",
  );
  out.push("  switch (type) {");
  for (const message of model.messages) {
    out.push(`    case ${literal(message.type)}:`);
    out.push(`      validate${payloadTypeName(model, message)}(value, path, out);`);
    out.push("      return;");
  }
  out.push("  }");
  out.push("}\n");

  pushDoc(out, "Builds the typed frame for a validated envelope and payload.");
  out.push(
    "export function decodeFrame(envelope: Envelope, value: unknown): ConnectorFrame {",
  );
  out.push("  switch (envelope.type) {");
  for (const message of model.messages) {
    out.push(`    case ${literal(message.type)}:`);
    out.push(
      `      return { envelope, type: ${literal(message.type)}, payload: decode${payloadTypeName(model, message)}(value) };`,
    );
  }
  out.push("  }");
  out.push("}\n");

  pushDoc(out, "Canonically encodes the payload of a typed frame.");
  out.push("export function encodeFramePayload(frame: ConnectorFrame): string {");
  out.push("  switch (frame.type) {");
  for (const message of model.messages) {
    out.push(`    case ${literal(message.type)}:`);
    out.push(`      return encode${payloadTypeName(model, message)}(frame.payload);`);
  }
  out.push("  }");
  out.push("}\n");

  return out.join("\n");
}

function payloadTypeName(model: ProtocolModel, message: MessageSpec): string {
  const node = model.defs.get(message.payloadDef);
  if (node === undefined || node.kind !== "object") {
    throw new Error(`payload ${message.payloadDef} is not an object`);
  }
  return node.typeName;
}

export function emitIndex(model: ProtocolModel): string {
  void model;
  return [
    BANNER,
    `export * from "./types.ts";`,
    `export * from "./validate.ts";`,
    `export * from "./decode.ts";`,
    `export * from "./encode.ts";`,
    `export * from "./dispatch.ts";`,
    "",
  ].join("\n");
}

export function arrayItemTypeName(model: ProtocolModel, node: ArrayNode): string {
  if (node.itemRef === null) return tsTypeOfNode(model, node.item);
  const target = resolveRef(model, node.itemRef);
  return target.kind === "object" ? target.typeName : tsScalarTypeName(node.itemRef, target);
}
